describe('Password Mismatch Error Validation', () => {
  beforeEach(() => {
    cy.visit('/')
    cy.get('[data-testid="password-input"]').as('passwordInput')
    cy.get('[data-testid="confirm-password-input"]').as('confirmPasswordInput')
    cy.get('[data-testid="password-error-message"]').as('errorMessage')
  })

  it('should display password mismatch error in real-time when passwords do not match', () => {
    cy.get('@passwordInput').type('SecurePass123!')
    cy.get('@confirmPasswordInput').type('DifferentPass456!')

    cy.get('@errorMessage')
      .should('be.visible')
      .and('contain', 'Passwords do not match')
  })

  it('should clear password mismatch error when passwords match', () => {
    cy.get('@passwordInput').type('SecurePass123!')
    cy.get('@confirmPasswordInput').type('DifferentPass456!')

    cy.get('@errorMessage')
      .should('be.visible')
      .and('contain', 'Passwords do not match')

    cy.get('@confirmPasswordInput').clear().type('SecurePass123!')

    cy.get('@errorMessage').should('not.be.visible')
  })

  it('should handle edge case of empty confirm password field', () => {
    cy.get('@passwordInput').type('SecurePass123!')
    cy.get('@confirmPasswordInput').focus().blur()

    cy.get('@errorMessage')
      .should('be.visible')
      .and('contain', 'Passwords do not match')
  })

  it('should validate on each keystroke in confirm password field', () => {
    cy.get('@passwordInput').type('Test1234')

    cy.get('@confirmPasswordInput').type('T')
    cy.get('@errorMessage').should('be.visible')

    cy.get('@confirmPasswordInput').type('e')
    cy.get('@errorMessage').should('be.visible')

    cy.get('@confirmPasswordInput').type('st1234')
    cy.get('@errorMessage').should('not.be.visible')
  })
})
